// Guided FS-12 captures reuse the ordinary Cartridge/DVS analyzer and owned
// native capture sessions. No output stimulus is generated by this workflow.
import { benchmarkConfig, benchmarkSteps, validateBenchmarkCapture, benchmarkStepRecord, guidedBenchmarkPayload } from '../../stylus-benchmark.js';
import { startLiveSession, liveAvailable } from '../audio-io.js';
import { runWithCapture, confirmCaptureBusy } from '../capture-busy.js';
import { buildRun } from '../analysis.js';
import { persistRun } from '../persistence.js';
import { settings, store, findProfile } from '../state.js';
import { createPairPicker, currentPairs } from '../pair-picker.js';
import { h } from '../dom.js';
import { TIMECODE_FORMATS } from '../../timecode.js';

const clone = value => JSON.parse(JSON.stringify(value));
const message = error => error?.message || String(error);
const stoppedError = () => Object.assign(new Error('The benchmark capture was cancelled.'), { cancelled: true });

async function ownedCapture({ signal, ...options }) {
  const start = () => signal.aborted ? Promise.reject(stoppedError()) : startLiveSession(options);
  return runWithCapture(start, {
    action: 'record the stylus benchmark',
    confirm: async (busy, options) => (await confirmCaptureBusy(busy, options)) && !signal.aborted,
  });
}

/** Stateful capture protocol with injectable I/O and deterministic lifecycle tests. */
export function createGuidedBenchmark({
  config: input, history = [], capture = ownedCapture, analyze = buildRun, persist = persistRun,
  save, profileFor = findProfile, now = Date.now, clock = () => performance.now(), timers = globalThis, onChange = () => {},
}) {
  const config = benchmarkConfig(input), steps = benchmarkSteps(config), prior = clone(history), records = [];
  let generation = 0, disposed = false, pending = null, timer = null;
  let state = { phase: 'ready', index: 0, elapsed: 0, error: null, payload: null };
  const snapshot = () => ({ ...state, config: clone(config), step: steps[state.index] || null, total: steps.length, completed: records.length });
  const emit = () => { if (!disposed) onChange(snapshot()); };
  const set = patch => { state = { ...state, ...patch }; emit(); };
  const current = mine => !disposed && generation === mine;
  const clearTimer = () => { if (timer !== null) timers.clearInterval(timer); timer = null; };
  const release = work => {
    work?.abort.abort();
    try { if (work?.session && !work.session.stopped) Promise.resolve(work.session.cancel()).catch(() => {}); } catch { /* owned cleanup must not replace the capture error */ }
  };
  function cancel(reason = 'Benchmark cancelled. Completed captures remain in History; no benchmark was saved.') {
    // A dispatched database write cannot be rolled back by cancelling the UI.
    if (disposed || ['saving', 'saved', 'cancelled'].includes(state.phase)) return false;
    generation += 1;
    clearTimer();
    const work = pending; pending = null;
    release(work);
    set({ phase: 'cancelled', error: reason });
    return true;
  }
  function fail(mine, error) {
    if (!current(mine)) return;
    generation += 1;
    clearTimer();
    const work = pending; pending = null;
    release(work);
    set({ phase: 'error', error: message(error), elapsed: 0 });
  }

  async function record() {
    if (disposed || !['ready', 'error'].includes(state.phase)) return;
    const step = steps[records.length], mine = ++generation;
    const work = { abort: new AbortController(), session: null, startedAt: null, startedClock: null, finishing: false };
    pending = work;
    set({ phase: 'opening', index: records.length, elapsed: 0, error: null });
    try {
      const session = await capture({
        signal: work.abort.signal, deviceName: config.deviceName || null, pairs: config.pairs,
        maxSeconds: step.seconds + 5,
        onPreempted: () => fail(mine, new Error('Another feature took over the input. Repeat this step.')),
        onStatus: status => { if (!work.finishing && status?.running === false) fail(mine, new Error('The input stopped before the capture completed. Repeat this step.')); },
      });
      if (!current(mine)) { await session.cancel(); return; }
      work.session = session; work.startedAt = now(); work.startedClock = clock();
      set({ phase: 'recording' });
      timer = timers.setInterval(() => {
        if (!current(mine) || work.finishing) return;
        const elapsed = session.elapsed();
        if (!Number.isFinite(elapsed) || elapsed < 0) { fail(mine, new Error('The capture timer is unavailable. Repeat this step.')); return; }
        set({ elapsed: Math.min(elapsed, step.seconds) });
        if (elapsed >= step.seconds) void finish();
        else if (clock() - work.startedClock > (step.seconds + 5) * 1000) fail(mine, new Error('The capture stopped making progress. Repeat this step.'));
      }, 100);
    } catch (error) { fail(mine, error); }
  }

  async function finish() {
    const work = pending, mine = generation, step = steps[records.length];
    if (disposed || state.phase !== 'recording' || !work?.session || work.finishing) return;
    work.finishing = true; clearTimer();
    set({ phase: 'analysing' });
    try {
      const result = await work.session.stop();
      if (!current(mine)) return;
      validateBenchmarkCapture(result, step);
      const profile = profileFor(result.deviceName, result.audio.sampleRate);
      const run = await analyze({
        test: step.test, workflowId: step.id === 'timecode' ? 'dvs' : 'cartridge', audio: result.audio,
        params: { referenceHz: 1000, nominalRpm: config.nominalRpm, separationActive: step.id === 'right' ? 'right' : 'left', timecodeFormat: config.timecodeFormat },
        source: `Live capture · ${result.deviceName}`, device: { id: config.assetId, name: config.assetName }, prior: [],
        quality: result.quality, streamErrors: result.streamErrors, profile, deviceName: result.deviceName,
        capture: { kind: 'live', startedAt: new Date(work.startedAt).toISOString(), endedAt: new Date(now()).toISOString() },
      });
      if (!current(mine)) return;
      run.setupId = config.setupId;
      const record = benchmarkStepRecord(step, result, run, profile);
      const saved = await persist(run);
      if (!current(mine)) return;
      if (!saved?.ok) throw new Error(`The capture could not be saved to History: ${saved?.error || 'database write failed'}. Repeat this step after resolving storage.`);
      records.push(record); pending = null;
      if (records.length === steps.length) set({ phase: 'review', payload: guidedBenchmarkPayload(config, records, prior), error: null });
      else set({ phase: 'ready', index: records.length, elapsed: 0, error: null });
    } catch (error) { fail(mine, error); }
  }

  async function saveBenchmark() {
    if (disposed || state.phase !== 'review' || !state.payload) return;
    const mine = ++generation, payload = clone(state.payload);
    set({ phase: 'saving', error: null });
    try {
      const result = await save(payload);
      if (current(mine)) set({ phase: 'saved', saved: result });
    } catch (error) { if (current(mine)) set({ phase: 'review', error: `Benchmark was not saved: ${message(error)}` }); }
  }

  return {
    snapshot, record, finish, save: saveBenchmark, cancel,
    dispose() { if (disposed) return; disposed = true; generation += 1; clearTimer(); const work = pending; pending = null; release(work); },
  };
}

/** Additive panel: the existing manual benchmark and History paths remain available. */
export function mountGuidedBenchmark(host, { asset, hoursAt, history = [], api, onSaved = () => {}, io = {} }) {
  let disposed = false, runner = null, pair = null, lastView = '', state = null, savedNotified = false;
  const native = io.liveAvailable || liveAvailable;
  const cleanupPair = () => { pair?.el?.dispatchEvent?.(new Event('pair-picker-dispose')); pair = null; };
  const textField = (id, label, value = '', options = {}) => h('div', { class: 'field' },
    h('label', { class: 'field-label', for: id, text: label }), h('input', { id, type: options.type || 'text', value, maxlength: '200', ...options }));
  const button = (id, label, action, primary = false) => h('button', { id, type: 'button', class: `btn ${primary ? 'btn-primary' : 'btn-secondary'}`, text: label, onclick: action });

  function setup() {
    if (disposed) return;
    runner?.dispose(); runner = null; cleanupPair(); lastView = ''; savedNotified = false;
    const old = history.find(row => row.valid !== false && row.valid !== 0 && row.detail?.source === 'guided-capture')?.detail?.conditions || {};
    const form = h('form', { class: 'card sty-form', id: 'sty-guided-config', novalidate: true });
    const error = h('p', { id: 'sty-guided-error', role: 'alert', class: 'form-error' });
    const setupSelect = h('select', { id: 'sty-guided-setup' }, h('option', { value: '', text: 'No saved setup — record the chain below' }));
    const rpm = h('select', { id: 'sty-guided-rpm' }, ...[[33.333333, '33⅓ RPM'], [45, '45 RPM']].map(([value, label]) => h('option', { value, text: label, selected: value === (old.nominalRpm || 33.333333) })));
    const format = h('select', { id: 'sty-guided-timecode' }, h('option', { value: '', text: 'Skip — no control-vinyl measurement' }), ...TIMECODE_FORMATS.map(f => h('option', { value: f.name, text: f.name, selected: f.name === old.timecodeFormat })));
    const sameConditions = h('input', { type: 'checkbox', id: 'sty-guided-same', checked: !history.length });
    pair = (io.createPairPicker || createPairPicker)({ id: 'sty-guided-pair' });
    const fields = h('div', { class: 'field-grid' },
      textField('sty-guided-record', 'Reference record', old.record || ''), textField('sty-guided-side', 'Reference side', old.side || 'A'),
      textField('sty-guided-force', 'Tracking force (g)', old.trackingForce ?? '', { type: 'number', step: 'any', min: '0' }),
      textField('sty-guided-vta', 'VTA / tonearm setting', old.vta || ''),
      textField('sty-guided-chain', 'Signal chain and gain settings', old.chain || ''),
      h('div', { class: 'field' }, h('label', { for: 'sty-guided-setup', text: 'Saved setup (optional)' }), setupSelect),
      h('div', { class: 'field' }, h('label', { for: 'sty-guided-rpm', text: 'Record speed' }), rpm),
      h('div', { class: 'field' }, h('label', { for: 'sty-guided-timecode', text: 'Optional control vinyl' }), format), pair.el);
    form.append(h('h3', { text: 'Guided stylus benchmark', tabindex: '-1' }),
      h('p', { class: 'muted', text: `Record ${asset.name}: stereo 1 kHz, left-only, right-only, then optional control vinyl. Choose the input in the top bar. Each complete capture is saved to History.` }),
      fields, h('label', { class: 'sty-check', for: 'sty-guided-same' }, sameConditions, h('span', { text: 'I recorded the conditions accurately and kept them the same as the baseline, if there is one.' })),
      history.length ? h('p', { class: 'muted small', text: 'Known setup or calibration changes exclude the benchmark from trends. Older manual benchmarks have no recorded setup to compare; the checkbox records your confirmation.' }) : null,
      error, h('button', { type: 'submit', class: 'btn btn-primary', id: 'sty-guided-start', text: 'Prepare guided captures', disabled: !native() }));
    host.replaceChildren(form);
    if (!native()) error.textContent = 'Guided capture needs the desktop audio input.';
    Promise.resolve((io.listSetups || (() => store.list('setup')))()).then(rows => {
      if (disposed || !setupSelect.isConnected) return;
      for (const row of rows || []) setupSelect.append(h('option', { value: row.id, text: row.name || row.id, selected: row.id === old.setupId }));
    }).catch(() => { if (!disposed && error.isConnected) error.textContent = 'Saved setups could not be loaded. Record the signal chain in the field above.'; });
    form.addEventListener('submit', event => {
      event.preventDefault();
      if (disposed || runner) return;
      const value = id => form.querySelector(`#${id}`).value;
      try {
        const config = benchmarkConfig({
          assetId: asset.id, assetName: asset.name, hoursAt,
          record: value('sty-guided-record'), side: value('sty-guided-side'), trackingForce: Number(value('sty-guided-force')),
          vta: value('sty-guided-vta'), chain: value('sty-guided-chain'), setupId: setupSelect.value,
          nominalRpm: Number(rpm.value), timecodeFormat: format.value, sameConditions: sameConditions.checked,
          deviceName: io.deviceName?.() ?? settings.deviceName, pairs: (io.currentPairs || currentPairs)(),
        });
        cleanupPair();
        runner = createGuidedBenchmark({ config, history, save: payload => api.benchmarkSave(payload), ...io, onChange: renderState });
        renderState(runner.snapshot());
      } catch (e) { error.textContent = message(e); }
    });
  }

  function renderState(next) {
    if (disposed) return;
    state = next;
    const view = `${next.phase}:${next.index}`;
    if (view === lastView && next.phase === 'recording') {
      const p = host.querySelector('#sty-guided-progress');
      if (p) p.value = next.elapsed;
      const elapsed = host.querySelector('#sty-guided-elapsed');
      if (elapsed) elapsed.textContent = `${Math.floor(next.elapsed)} of ${next.step.seconds} seconds`;
      return;
    }
    lastView = view;
    const card = h('section', { class: 'card', 'aria-label': 'Guided benchmark progress' });
    const status = h('p', { id: 'sty-guided-status', role: 'status', 'aria-live': 'polite' });
    card.append(h('h3', { text: 'Guided stylus benchmark' }), status);
    let focus = null;
    if (['ready', 'error', 'opening', 'recording', 'analysing'].includes(next.phase)) {
      status.textContent = `Step ${next.index + 1} of ${next.total}: ${next.step.label}. ${next.completed} captures saved.`;
      card.append(h('p', { text: next.step.instruction }));
      if (next.error) card.append(h('p', { role: 'alert', class: 'form-error', text: next.error }));
      if (next.phase === 'ready' || next.phase === 'error') {
        focus = button('sty-guided-record-step', `Record ${next.step.seconds} seconds`, () => void runner.record(), true);
        card.append(focus);
      } else {
        card.append(h('p', { text: next.phase === 'opening' ? 'Opening the selected input…' : next.phase === 'analysing' ? 'Analysing and saving this capture…' : 'Recording. Stop discards this step.' }),
          h('progress', { id: 'sty-guided-progress', max: next.step.seconds, value: next.elapsed, 'aria-label': `${next.step.label} recording` }),
          h('span', { id: 'sty-guided-elapsed', text: `${Math.floor(next.elapsed)} of ${next.step.seconds} seconds` }));
      }
      const cancel = button('sty-guided-cancel', 'Cancel benchmark (Esc)', () => runner.cancel());
      card.append(cancel); focus ||= cancel;
    } else if (next.phase === 'review' || next.phase === 'saving') {
      status.textContent = next.phase === 'saving' ? 'Saving the benchmark. The storage write will continue if you leave this screen.' : next.payload.valid ? 'Captures complete. Review the measured values before saving to the trend.' : 'Captures complete. This benchmark will be saved as excluded from the trend.';
      const rows = [['THD, mean of L/R', next.payload.thdPercent, '%'], ['Separation, poorer isolated channel', next.payload.separationDb, 'dB']];
      if (next.payload.tcSnrDb !== undefined) rows.push(['Timecode SNR', next.payload.tcSnrDb, 'dB'], ['Timecode phase error', next.payload.tcPhaseErrorDeg, '°'], ['Timecode dropouts', next.payload.tcDropouts, '']);
      const list = h('dl', { class: 'kv' });
      for (const [label, value, unit] of rows) list.append(h('dt', { text: label }), h('dd', { text: `${Number(value.toFixed(3))} ${unit}` }));
      card.append(list, h('p', { class: 'muted', text: `${next.config.assetName} · ${next.config.hoursAt} h · ${next.config.record}, side ${next.config.side}. ${next.total} source runs remain in History.` }));
      if (next.payload.detail.issues.length) card.append(h('ul', {}, ...next.payload.detail.issues.map(issue => h('li', { text: issue }))));
      if (next.error) card.append(h('p', { role: 'alert', class: 'form-error', text: next.error }));
      focus = button('sty-guided-save', next.phase === 'saving' ? 'Saving…' : next.payload.valid ? 'Save benchmark' : 'Save excluded benchmark', () => void runner.save(), true);
      focus.disabled = next.phase === 'saving';
      card.append(focus);
      if (next.phase === 'saving') { status.tabIndex = -1; focus = status; }
      else card.append(button('sty-guided-cancel', 'Cancel benchmark (Esc)', () => runner.cancel()));
    } else {
      status.textContent = next.phase === 'saved' ? (next.payload.valid ? 'Guided benchmark saved.' : 'Guided benchmark saved and excluded from the trend.') : next.error;
      focus = button('sty-guided-again', 'Prepare another benchmark', setup);
      card.append(focus);
    }
    host.replaceChildren(card); focus?.focus();
    if (next.phase === 'saved' && !savedNotified) { savedNotified = true; onSaved(next.payload); }
  }

  host.addEventListener('keydown', event => {
    if (disposed || !runner) return;
    if (event.key === 'Escape') { event.preventDefault(); event.stopPropagation(); runner.cancel(); }
    else if (event.key === 'Enter' && ['ready', 'error'].includes(state?.phase) && event.target?.tagName !== 'BUTTON') { event.preventDefault(); void runner.record(); }
  });
  setup();
  return {
    cancel() { if (!runner || ['saved', 'cancelled'].includes(state?.phase)) return false; runner.cancel(); return true; },
    dispose() { if (disposed) return; disposed = true; runner?.dispose(); cleanupPair(); },
  };
}
